set -eu
install -d -m 0755 /srv/legacy2/mail-filter-routing/bin
cat > /srv/legacy2/mail-filter-routing/bin/deliver <<'DELIVER_EOF'
#!/bin/sh
set -eu

base=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)
maildir=$base/Maildir
umask 077

for box in accounts support general; do
    mkdir -p -- "$maildir/$box/new"
done
mkdir -p -- "$maildir/tmp"

tmp=$(mktemp "$maildir/tmp/deliver.$$.XXXXXXXXXX")
trap 'rm -f -- "$tmp"' EXIT HUP INT TERM
cat > "$tmp"

department=$(
    awk '
        function trim(value) {
            sub(/^[ \t]+/, "", value)
            sub(/[ \t]+$/, "", value)
            return value
        }
        function route(value) {
            value = trim(value)
            if (value == "accounts" || value == "support") {
                print value
                routed = 1
                exit
            }
        }
        BEGIN {
            in_department = 0
            value = ""
        }
        {
            line = $0
            sub(/\r$/, "", line)

            if (line == "") {
                if (in_department)
                    route(value)
                exit
            }

            if (line ~ /^[ \t]/) {
                if (in_department) {
                    continuation = line
                    sub(/^[ \t]+/, "", continuation)
                    value = value " " continuation
                }
                next
            }

            if (in_department) {
                route(value)
                in_department = 0
                value = ""
            }

            separator = index(line, ":")
            if (separator == 0)
                next

            name = tolower(substr(line, 1, separator - 1))
            if (name == "x-department") {
                in_department = 1
                value = substr(line, separator + 1)
            }
        }
        END {
            if (!routed) {
                if (in_department) {
                    final_value = trim(value)
                    if (final_value == "accounts" || final_value == "support") {
                        print final_value
                        routed = 1
                    }
                }
                if (!routed)
                    print "general"
            }
        }
    ' "$tmp"
)

name=$(date +%s).$$.${tmp##*.}
destination=$maildir/$department/new/$name
if [ -e "$destination" ]; then
    printf '%s\n' "delivery name collision: $destination" >&2
    exit 1
fi
mv -- "$tmp" "$destination"
trap - EXIT HUP INT TERM
DELIVER_EOF
chmod 0755 /srv/legacy2/mail-filter-routing/bin/deliver
/bin/sh -n /srv/legacy2/mail-filter-routing/bin/deliver
printf 'installed_sha256='; sha256sum /srv/legacy2/mail-filter-routing/bin/deliver | cut -d' ' -f1
printf 'mode='; stat -c '%A %U:%G' /srv/legacy2/mail-filter-routing/bin/deliver

